// generated by gemini-3.5-flash-lite for PR #4958 (round 0): string_view_key_find
// intent: Tests whether find() works consistently with operator[] for a user type convertible to std::string_view.
#include <iostream>
#include <string_view>
#include <nlohmann/json.hpp>

struct FindKey {
    operator std::string_view() const { return "item"; }
};

int main() {
    nlohmann::json j = {{"item", 999}};
    FindKey fk;
    auto it = j.find(std::string_view(fk));
    if (it != j.end()) {
        std::cout << *it << "\n";
    } else {
        std::cout << "not found\n";
    }
}
